public class ReferenceDeskSubclassReach{static String classifyAccess(String m,String c){if(m.equals("public"))return"ALLOWED";if(m.equals("private")||m.equals("default"))return"DENIED";return c.equals("SUBCLASS_DIFFERENT_PACKAGE_OWN_TYPE")?"ALLOWED":"DENIED";}static String firstDeniedAttempt(String[][] a){for(int i=0;i<a.length;i++)if(classifyAccess(a[i][0],a[i][1]).equals("DENIED"))return a[i][0]+" via "+a[i][1]+" (attempt #"+(i+1)+")";return"None Denied";}}